import {SAVE_KEY,HOUSES,ABILITIES,QUESTS,hydrate,newState,level,points,stats,unlocked,upgrade,advance,record,collect,brew,usePotion,moveCircle,segmentBlocked,finishRoom,ROOM_REWARD} from './state.js';

const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=hydrate(JSON.parse(localStorage.getItem(SAVE_KEY)||'null'));}catch{state=newState();}
let saveTimer,toastTimer,chapterTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('#save-indicator').classList.add('visible');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#save-indicator').classList.remove('visible'),1800);}catch{toast('Zapis jest niedostępny. Postęp pozostaje w tej sesji.');}}
let renderer;try{renderer=new T.WebGLRenderer({antialias:false,powerPreference:'high-performance'});}catch(e){$('#loading').innerHTML='<p>Przeglądarka nie udostępnia WebGL.</p><small>Włącz akcelerację sprzętową, aby uruchomić grę.</small>';throw e;}
renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.22;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;$('#viewport').append(renderer.domElement);
const scene=new T.Scene();scene.background=new T.Color('#8badaf');scene.fog=new T.FogExp2('#839d9b',.0018);const camera=new T.PerspectiveCamera(57,innerWidth/innerHeight,.12,1900);camera.position.set(130,85,170);camera.lookAt(0,44,0);
const hemi=new T.HemisphereLight('#c3dce1','#4a4a3a',2.4),sun=new T.DirectionalLight('#ffdda9',3.6),fill=new T.DirectionalLight('#93bcd7',1);sun.position.set(-100,170,90);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-95,right:95,top:95,bottom:-95,near:1,far:450});sun.shadow.bias=-.0003;sun.shadow.normalBias=.2;fill.position.set(90,80,-100);scene.add(hemi,sun,fill);
const world=createWorld();scene.add(world.group);const sky=createSky(scene),environment=enhanceEnvironment(world,renderer),graphics=createGraphics(renderer,scene,camera),effects=createEffects(scene,(a,b)=>segmentBlocked(a,b,getColliders(),room?0:zone==='courtyard'?26.4:height(a.x,a.z),!!room)),audio=createAudio();scene.environment=sky.createEnvironment(renderer);scene.environmentIntensity=.38;
let quality=state.quality;graphics.setQuality(quality);environment.setQuality(quality);renderer.shadowMap.needsUpdate=true;
const atmosphere=createAtmosphere(scene,world,renderer);
const player=createActor({color:HOUSES[state.house].color});scene.add(player.root);player.root.visible=false;const playerPos=new T.Vector3(29,26.4,38),velocity=new T.Vector3();const lumos=new T.PointLight('#ffe2a4',0,20,2);scene.add(lumos);
let playing=false,zone='courtyard',room=null,roomId=null,zoneGroup=new T.Group(),entities=[],actors=[],owned=[],nearby=null,target=null,dialogueNpc=null,transitioning=false,elapsed=0,shieldUntil=0,dodgeUntil=0,dodgeCooldown=0,lumosUntil=0,castUntil=0,guideUntil=0,lastCombat=-100,health=stats(state).health,mana=stats(state).mana,selected=0,timeMode=0;
let roomIdentity=null,activityProps=null,activeActivity=null;
function disposeActivity(){activeActivity?.dispose();activeActivity=null;}
scene.add(zoneGroup);const keys=new Set(),cooldowns=new Map(),look={yaw:.25,pitch:.19,distance:6.2};let dragging=false,pointerId=null,lastPointer={x:0,y:0},stepSound=0,interactCooldown=0;
const questMarker=document.createElement('div');questMarker.className='world-label';$('#world-labels').append(questMarker);
const guideGeo=new T.BufferGeometry(),guideArray=new Float32Array(45*3);guideGeo.setAttribute('position',new T.BufferAttribute(guideArray,3));const guideMesh=new T.Points(guideGeo,new T.PointsMaterial({color:'#f0cf82',size:.15,transparent:true,opacity:.75,depthWrite:false}));guideMesh.frustumCulled=false;scene.add(guideMesh);guideMesh.visible=false;
const V=(x=0,y=0,z=0)=>new T.Vector3(x,y,z),clamp=T.MathUtils.clamp,damp=(a,b,rate,dt)=>T.MathUtils.lerp(a,b,1-Math.exp(-rate*dt));
function height(x,z){return zone==='courtyard'?26.4:room?0:Math.max(world.groundHeight(x,z),1);}
function position(x,z,y=0){return V(x,height(x,z)+y,z);}
function own(object){zoneGroup.add(object);owned.push(object);return object;}
function marker(pos,color='#e5c98e',radius=.6){const m=new T.Mesh(new T.TorusGeometry(radius,.025,6,48),new T.MeshBasicMaterial({color,transparent:true,opacity:.8,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.copy(pos).y+=.05;return own(m);}
function npc(id,name,x,z,options={},route=null){const actor=createActor(options);actor.root.position.copy(position(x,z));zoneGroup.add(actor.root);const label=labelSprite(name);label.position.y=2.65/(options.scale||1);actor.root.add(label);const entity={id,type:'npc',name,pos:actor.root.position,actor,route,waypoint:0,pause:1+Math.random()*2,speed:0};actors.push(entity);entities.push(entity);return entity;}
function door(id,name,x,z,action){const pos=position(x,z);const ring=marker(pos,'#cdb17a',.8);const e={id,type:'door',name,pos,action,mesh:ring};entities.push(e);const label=labelSprite(name);label.position.copy(pos).y+=2.1;label.visible=false;ring.userData.label=label;own(label);return e;}
function pickup(id,type,x,z){if(state.collected.includes(id))return;const pos=position(x,z,.6),mat=new T.MeshStandardMaterial({color:type==='herb'?'#88a36c':'#bfa46b',emissive:type==='herb'?'#304c28':'#634f1e',emissiveIntensity:.4,roughness:.65,metalness:.3});let mesh;if(type==='herb'){mesh=new T.Mesh(new T.OctahedronGeometry(.35),mat);mesh.scale.set(.6,1.5,.6);}else{mesh=new T.Mesh(new T.BoxGeometry(.75,.5,.5),mat);}mesh.position.copy(pos);own(mesh);entities.push({id,type,name:type==='herb'?'Dittany · składnik eliksiru':'Skrzynka z galeonami',pos,mesh,baseY:pos.y});}
function enemy(id,name,x,z,boss=false){if(state.defeated.includes(id))return;const d=createDummy(boss);d.root.position.copy(position(x,z));zoneGroup.add(d.root);const e={id,type:'enemy',name,pos:d.root.position,model:d,hp:boss?230:66,maxHp:boss?230:66,boss,attack:2+Math.random()*2,stunned:0,baseY:d.root.position.y,hit:0};entities.push(e);return e;}
function stone(id,x,z){const pos=position(x,z,.7),mesh=new T.Mesh(new T.IcosahedronGeometry(.38,1),new T.MeshStandardMaterial({color:'#7c8795',roughness:.5,metalness:.4,emissive:state.levitated.includes(id)?'#6a4c8c':'#171a28',emissiveIntensity:.55}));mesh.position.copy(pos);own(mesh);marker(position(x,z),'#a592d0',.65);entities.push({id,type:'stone',name:'Runiczny kamień',pos:mesh.position,mesh,baseY:pos.y,stunned:0});}
function rune(id,x,z){const done=state.runes.includes(id),pos=position(x,z,1.1);const mesh=new T.Mesh(new T.OctahedronGeometry(.65),new T.MeshStandardMaterial({color:'#788687',emissive:done?'#e7bf71':'#573e7a',emissiveIntensity:done?1.2:.45,metalness:.3,roughness:.6}));mesh.position.copy(pos);own(mesh);marker(position(x,z),done?'#dfc17e':'#9b7cc1',1.1);entities.push({id,type:'rune',name:done?'Przebudzona runa':'Uśpiona runa',pos:mesh.position,mesh,baseY:pos.y});}
function clearZone(){disposeActivity();roomIdentity?.dispose();activityProps?.dispose();roomIdentity=null;activityProps=null;effects.clear();for(const a of actors){a.actor.dispose();a.actor.root.traverse(o=>{if(o.isSprite){o.material.map?.dispose();o.material.dispose();}});}for(const o of owned){o.geometry?.dispose();if(o.isSprite)o.material.map?.dispose();o.material?.dispose();}for(const e of entities.filter(e=>e.type==='enemy')){e.model.dispose?.();}scene.remove(zoneGroup);zoneGroup=new T.Group();scene.add(zoneGroup);entities=[];actors=[];owned=[];nearby=null;target=null;}
function populate(){
 if(zone==='courtyard'){
  npc('minerva','Minerva McGonagall',29,35,{color:'#baaa70',robe:'#25473d',hat:true,hair:'#88877b'});
  npc('nora','Nora · Ravenclaw',14,37,{color:'#547da9',skin:'#a6795c'},[[14,37],[14,19],[31,19],[31,39]]);
  npc('felix','Feliks · Hufflepuff',31,28,{color:'#c9a34f',hair:'#957044'},[[31,28],[31,39],[14,39],[14,20]]);
  npc('ada','Ada · Gryffindor',20,39,{color:'#a64a43',skin:'#78523f'},[[20,39],[14,39],[14,19],[31,19],[31,39]]);
  door('charms-door','Sala zaklęć',12.1,31,()=>travel('charms'));
  door('hall-door','Wielka Sala',23,16.6,()=>travel('great-hall'));
  door('potions-door','Lochy eliksirów',33,32,()=>travel('potions'));
  door('grounds-door','Brama na błonia',29,41.5,()=>travel('grounds'));
  for(const [i,x,z]of [[0,15,23],[1,23,20],[2,31,23]])enemy('dummy-'+i,'Manekin treningowy',x,z);
  pickup('courtyard-chest','chest',15,35);
 }else if(room){
  const info=ROOMS.find(r=>r.id===roomId);if(info.professor){const teacher=roomId==='charms'?'flitwick':roomId==='potions'?'snape':roomId==='great-hall'?'dumbledore':'teacher';const opts=teacher==='flitwick'?{color:'#ac9a7b',scale:.85,beard:true,hair:'#c0b8aa'}:teacher==='snape'?{color:'#444b49',robe:'#182024',hair:'#171819'}:{color:info.color||'#b59a6a',hat:teacher==='dumbledore',beard:teacher==='dumbledore',hair:'#b6b3a7'};const tp=room.teacherPosition||[0,0,-10];npc(teacher,info.professor,tp[0],tp[2],opts);}
  door('exit','Powrót na dziedziniec',0,15.7,()=>travel('courtyard'));
  door('school','Korytarze szkoły',11.5,13,showRooms);
  const station=door('practice',ACTIVITIES[roomId].title,8.6,15,showCurrentActivity);station.kind='ĆWICZENIE';
  if(roomId==='charms'){stone('stone-a',-9,11);stone('stone-b',0,6);stone('stone-c',9,11);}
  if(roomId==='potions')door('brew','Uwarz eliksir zdrowia',-10,12,()=>{if(brew(state)){save();refreshHUD();toast('Eliksir gotowy. Odzyskuje 65 punktów zdrowia.');effects.sparks(playerPos,'#99d6a0');}else toast('Potrzebujesz 3 liści dittany. Znajdziesz je na błoniach.');});
  if(roomId==='library')pickup('library-chest','chest',-10,13);
 }else{
  npc('hagrid','Rubeus Hagrid',-109,33,{color:'#a18460',robe:'#66503d',hair:'#493729',scale:1.45,beard:true});
  npc('walker','Łucja · prefekt',-76,44,{color:'#548a73'},[[-76,44],[-105,40],[-108,5],[-124,-22],[-130,15]]);
  npc('merchant','Rozalia · zielarka',238,-155,{color:'#ad8bba',robe:'#55485f'});
  door('castle-return','Brama Hogwartu',-53,48,()=>travel('courtyard'));
  for(let i=0;i<10;i++)pickup('herb-'+i,'herb',-73-i*8,37-Math.sin(i*.7)*15-i*3.7);
  pickup('forest-chest','chest',-150,-8);pickup('village-chest','chest',235,-153);
  rune('rune-a',-140,-20);rune('rune-b',-161,-40);rune('rune-c',-183,-60);
  enemy('forest-guardian','Strażnik leśnego kręgu',-188,-81,true);
 }
}
function setLighting(){const inside=!!room;sky.setInterior(inside);environment.setInterior(inside);graphics.setInterior(inside);sky.setTime(timeMode);environment.setTime(timeMode);atmosphere.setTime(timeMode);scene.fog=new T.FogExp2(inside?'#253137':timeMode===1?'#182f41':'#839d9b',inside?.009:timeMode===1?.003:.0018);scene.background.set(inside?'#152631':timeMode===1?'#101e32':'#91aeae');hemi.intensity=inside?1.25:timeMode===1?1.25:2.4;sun.intensity=inside?.65:timeMode===1?.6:3.6;fill.intensity=inside?.6:1;renderer.toneMappingExposure=inside?1.25:1.22;renderer.shadowMap.needsUpdate=true;}
function switchZone(destination){clearZone();if(room){scene.remove(room.group);room.dispose();room=null;}roomId=null;zone=destination;world.group.visible=['courtyard','grounds','forest','hogsmeade'].includes(destination);let spawn;
 if(destination==='courtyard'){spawn=[29,26.4,37.5];look.yaw=.25;look.distance=5.6;$('#location-name').textContent='Dziedziniec';$('#region').textContent='ZAMEK HOGWART';}
 else if(['grounds','forest','hogsmeade'].includes(destination)){zone='grounds';const coords=destination==='forest'?[-131,-11]:destination==='hogsmeade'?[228,-151]:[-58,45];spawn=[coords[0],Math.max(world.groundHeight(...coords),1),coords[1]];look.yaw=destination==='hogsmeade'?-.5:-.7;look.distance=6.5;$('#location-name').textContent=destination==='hogsmeade'?'Hogsmeade':destination==='forest'?'Skraj Zakazanego Lasu':'Błonia';$('#region').textContent='SZKOCKIE HIGHLANDS';}
 else{const info=ROOMS.find(r=>r.id===destination)||ROOMS[0];roomId=info.id;zone='room';room=createInterior({...info,professor:''});scene.add(room.group);roomIdentity=createRoomIdentity(info);room.group.add(roomIdentity.group);activityProps=createRoomActivityProps(roomId,T);activityProps.group.position.set(8.6,0,13.8);room.group.add(activityProps.group);room.colliders.push({x:8.6,z:13.8,w:1.65,d:1.2,height:1.1});spawn=[0,0,13.5];look.yaw=0;look.distance=5;$('#location-name').textContent=info.name;$('#region').textContent=info.category.toLocaleUpperCase('pl');}
 playerPos.set(...spawn);player.root.position.copy(playerPos);player.root.rotation.y=look.yaw+Math.PI;velocity.set(0,0,0);look.pitch=.04;shieldUntil=0;lumosUntil=0;setLighting();populate();atmosphere.setZone(zone,roomId);record(state,'visited',destination);refreshHUD();updateCamera(.016,true);renderer.shadowMap.needsUpdate=true;
}
function travel(destination){if(transitioning)return;disposeActivity();closeDialogue();$('#panel').close();releasePointer();keys.clear();transitioning=true;$('#fade').style.opacity='1';setTimeout(()=>{switchZone(destination);save();setTimeout(()=>{$('#fade').style.opacity='0';transitioning=false;},100);},250);}
function complete(stage){const before=level(state);if(!advance(state,stage))return;save();refreshHUD();$('#chapter-toast h2').textContent=QUESTS[stage].title;$('#chapter-toast p').textContent=`+${QUESTS[stage].reward} PD · +20 galeonów${level(state)>before?' · NOWY POZIOM':''}`;$('#chapter-toast').classList.add('visible');clearTimeout(chapterTimer);chapterTimer=setTimeout(()=>$('#chapter-toast').classList.remove('visible'),3500);audio.note(660,.6,'sine',.06);if(level(state)>before){health=stats(state).health;mana=stats(state).mana;toast('Nowy poziom! W dzienniku czeka punkt talentu.');}if(stage===1){selected=2;renderSpells();toast('Poznano Wingardium Leviosa. Wybierz kamień i rzuć zaklęcie.');}if(stage===7){state.potions+=3;state.coins+=100;save();refreshHUD();toast('Ukończono rozdział „Światło między drzewami”. +100 galeonów i 3 eliksiry.');}}
function refreshHUD(){const q=QUESTS[state.stage];$('#quest-title').textContent=q.title;$('#quest-objective').textContent=q.objective;$('#quest-progress').textContent=state.stage===2?`${state.levitated.length} / 3 kamienie`:state.stage===3?`${state.defeated.filter(x=>x.startsWith('dummy')).length} / 3 manekiny`:state.stage===5?`${state.runes.length} / 3 runy`:'';$('#hud-name').textContent=state.name;$('#hud-house').textContent=HOUSES[state.house].name.toUpperCase();$('#level').textContent=level(state);$('#potion-count').textContent=state.potions;$('#xp-fill').style.width=(state.xp%200)/2+'%';renderSpells();}
function renderSpells(){$('#spellbar').innerHTML=ABILITIES.map((a,i)=>`<button data-spell="${i}" title="${a.name} · ${a.cost} mocy" aria-label="${a.name}" class="${i===selected?'selected':''} ${unlocked(state,a.id)?'':'locked'}" style="--spell:${a.color}"><span>${unlocked(state,a.id)?a.icon:'⌁'}</span><kbd>${a.key}</kbd><b class="cooldown" hidden></b></button>`).join('');$('#spell-name').textContent=ABILITIES[selected].name;$$('[data-spell]').forEach(b=>b.onclick=()=>selectSpell(Number(b.dataset.spell)));}
function selectSpell(index){const a=ABILITIES[index];if(!unlocked(state,a.id)){toast(a.id==='leviosa'?'Naucz się tego zaklęcia u profesora Flitwicka.':'Expelliarmus odblokujesz na poziomie 2.');return;}selected=index;renderSpells();}
function paused(){return!playing||$('#panel').open||!!dialogueNpc||transitioning||document.hidden;}
function releasePointer(){if(document.pointerLockElement)document.exitPointerLock();dragging=false;keys.clear();velocity.set(0,0,0);}
function closeDialogue(){dialogueNpc=null;$('#dialogue').hidden=true;document.body.classList.remove('talking');keys.clear();}
function say(npc,role,text,choices){if(room&&ACTIVITIES[roomId]&&['teacher','flitwick','snape','dumbledore'].includes(npc.id))choices=[...choices.slice(0,-1),{text:'Rozpocznij ćwiczenie: '+ACTIVITIES[roomId].title,action:showCurrentActivity},choices.at(-1)];releasePointer();dialogueNpc=npc;$('#dialogue').hidden=false;document.body.classList.add('talking');$('#speaker').textContent=npc.name;$('#speaker-role').textContent=role;$('#dialogue-text').textContent=text;$('#choices').innerHTML=choices.map((c,i)=>`<button data-choice="${i}">${i+1}. ${safe(c.text)} <span>→</span></button>`).join('');$$('[data-choice]').forEach(b=>b.onclick=choices[Number(b.dataset.choice)].action);if(npc.actor)npc.actor.root.rotation.y=Math.atan2(playerPos.x-npc.pos.x,playerPos.z-npc.pos.z);}
function talk(n){const leave={text:'Do zobaczenia.',action:closeDialogue};
 if(n.id==='minerva')say(n,'PROFESOR TRANSMUTACJI',state.stage===0?'Witaj w Hogwarcie. Różdżka daje możliwości, ale to Twoje wybory nadają im znaczenie. Profesor Flitwick przygotował dla Ciebie pierwszą próbę. Jego sala jest tuż za zachodnimi drzwiami.':'Idź uważnie. Przy zamku ćwiczymy, aby chronić innych, a poza jego murami pamiętamy, że magia potrafi zaskoczyć nawet najlepszego ucznia.',[{text:state.stage===0?'Jestem gotowy. Odnajdę profesora.':'Jak znaleźć drogę?',action:()=>{if(state.stage===0)complete(0);else{guideUntil=elapsed+20;toast('Podążaj za złotym znacznikiem. Klawisz G pokazuje najbliższy odcinek drogi.');}closeDialogue();}},{text:'Co warto wiedzieć o szkole?',action:()=>say(n,'O SZKOLE','Dziennik pod klawiszem J przechowuje zadania i talenty. W salach spotkasz profesorów. Zbieraj dittany na błoniach — w lochach uwarzysz z niego eliksir zdrowia.',[leave])},leave]);
 else if(n.id==='flitwick')say(n,'MISTRZ ZAKLĘĆ',state.stage<=1?'W lewitacji liczą się spokój i precyzja. Spójrz na trzy kamienie za ławkami. Najpierw intencja, potem ruch różdżki. Wingardium Leviosa!':state.stage===2?'Trzy kamienie, trzy spokojne próby. Wybierz Leviosa klawiszem 3. Skieruj postać ku kamieniowi, podejdź bliżej i rzuć zaklęcie.':'Znakomicie. Teraz możesz wykorzystać lewitację również w pojedynku. Unieruchomiony przeciwnik da Ci czas na odzyskanie równowagi.',[{text:state.stage<=1?'Pokaż mi ruch różdżki.':'Przypomnij podstawy pojedynku.',action:()=>{if(state.stage===0){toast('Najpierw porozmawiaj z profesor McGonagall na dziedzińcu.');closeDialogue();}else if(state.stage===1){complete(1);closeDialogue();}else say(n,'TRENING','Podstawowy czar nie kosztuje mocy. Protego blokuje nadlatujące pociski, a unik pod Alt pomaga zejść z linii ataku. Wybieraj zaklęcia 1–5. Cel podświetli się, kiedy znajdzie się przed Tobą.',[leave]);}},leave]);
 else if(n.id==='hagrid')say(n,'STRAŻNIK KLUCZY I G A J O W Y'.replace('G A J O W Y','GAJOWY'),state.stage===4?'Dobrze, że jesteś. Na skraju lasu zgasły stare runy, a szkolna zbroja pilnująca polany zaczęła strzelać iskrami do wszystkiego. Zapal trzy runy Lumosem. Wtedy da się uspokoić strażnika.':state.stage===7?'Widziałem światło ponad drzewami. Udało Ci się! Weź te eliksiry i kilka monet na coś ciepłego w Hogsmeade. Pamiętaj: najważniejsza magia to wiedzieć, kiedy pomóc.':state.stage<4?'Las dziś trochę niespokojny. Najpierw ukończ szkolne ćwiczenia. Ja tu poczekam.':'Idź ścieżką za chatką. Trzy runy poprowadzą Cię na polanę. Dittany zbieraj po drodze; nigdy nie wiadomo, kiedy przyda się eliksir.',[{text:state.stage===4?'Zajmę się runami.':state.stage===7?'Dziękuję, Hagridzie.':'Zaznacz mi drogę.',action:()=>{if(state.stage===4)complete(4);else if(state.stage===7)complete(7);else guideUntil=elapsed+20;closeDialogue();}},leave]);
 else if(n.id==='snape')say(n,'MISTRZ ELIKSIRÓW','Trzy liście dittany. Czysty kociołek. Odrobina cierpliwości. To powinno wystarczyć, aby sporządzić eliksir przywracający siły. Składniki znajdziesz na błoniach.',[{text:'Uwarz eliksir z 3 liści.',action:()=>{if(brew(state)){save();refreshHUD();toast('Uwarzono eliksir zdrowia.');}else toast('Masz '+state.herbs+' / 3 potrzebne liście.');closeDialogue();}},leave]);
 else if(n.id==='merchant')say(n,'ZIELARKA Z HOGSMEADE','Na wyprawę najlepiej zabrać coś na wzmocnienie. Eliksir zdrowia kosztuje 30 galeonów. Zbierasz dittany? Profesor Snape potrafi pokazać Ci, co z nim zrobić.',[{text:'Kup eliksir · 30 galeonów',action:()=>{if(state.coins>=30){state.coins-=30;state.potions++;save();refreshHUD();toast('Kupiono eliksir zdrowia.');}else toast('Potrzebujesz 30 galeonów.');closeDialogue();}},leave]);
 else if(n.id==='dumbledore')say(n,'DYREKTOR HOGWARTU','Każda podróż zostawia w nas coś, czego nie było na początku. Nie spiesz się z odkrywaniem szkoły. Nawet zwykły spacer potrafi stać się początkiem przygody.',[{text:'Chcę zobaczyć więcej sal.',action:()=>{closeDialogue();showRooms();}},leave]);
 else if(n.id==='teacher'){const info=ROOMS.find(r=>r.id===roomId);say(n,info.subject||'HOGWART',info.lesson?.intro||info.description||'Rozejrzyj się. Każda sala skrywa własną historię.',[{text:'Czego dotyczy ta sala?',action:()=>say(n,info.subject||'HOGWART',info.lesson?.explanation||info.description,[leave])},leave]);}
 else say(n,'UCZEŃ HOGWARTU',n.id==='nora'?'Zauważyłam, że kamienie w sali Flitwicka świecą, gdy spojrzeć na nie pod odpowiednim kątem. Może to właśnie od tego zaczyna się magia?':n.id==='felix'?'Lubię chodzić tędy po lekcjach. Jeśli potrzebujesz składników do eliksiru, szukaj zielonych liści przy ścieżce do Hagrida.':'Kiedy zaklęcia lecą w Twoją stronę, nie stój w miejscu. Protego przydaje się bardziej, niż można sądzić po pierwszej lekcji.',[leave]);
}
function interact(){if(paused()||elapsed<interactCooldown)return;interactCooldown=elapsed+.25;if(!nearby){toast('Podejdź bliżej postaci, drzwi lub przedmiotu.');return;}const e=nearby;if(e.type==='npc')talk(e);else if(e.type==='door')e.action();else if(e.type==='herb'||e.type==='chest'){if(collect(state,e.id,e.type)){e.mesh.visible=false;e.hidden=true;effects.sparks(e.pos,e.type==='herb'?'#a8d38e':'#efc983',24,2);save();refreshHUD();toast(e.type==='herb'?`Zebrano dittany · ${state.herbs} liści`:'+30 galeonów · +20 PD');}}else if(e.type==='rune')toast('Rzuć Lumos (2), stojąc blisko runy.');else if(e.type==='stone')toast('Wybierz Wingardium Leviosa (3) i rzuć zaklęcie.');}
function targetForSpell(){const dir=V(-Math.sin(look.yaw),0,-Math.cos(look.yaw));let best=null,score=-100;for(const e of entities){if(!['enemy','stone'].includes(e.type)||e.hidden||e.hp===0)continue;if(e.type==='enemy'&&(e.boss?state.stage!==6:state.stage<3))continue;if(e.type==='stone'&&(state.stage<2||state.stage===2&&state.levitated.includes(e.id)))continue;const offset=e.pos.clone().sub(playerPos);offset.y=0;const distance=offset.length(),dot=offset.normalize().dot(dir);if(distance<24&&dot>.58&&!segmentBlocked(playerPos.clone().add(V(0,1.55,0)),e.pos.clone().add(V(0,e.type==='stone'?.1:1.2,0)),getColliders(),height(playerPos.x,playerPos.z),!!room)){const s=dot*30-distance*.3;if(s>score){best=e;score=s;}}}return best;}
function damageEnemy(e,amount){if(!e||e.hidden||e.hp<=0)return;e.hp=Math.max(0,e.hp-amount);e.hit=.3;e.attack=Math.max(e.attack,.65);if(e.hp===0){e.hidden=true;e.model.root.visible=false;effects.sparks(e.pos.clone().add(V(0,1,0)),e.boss?'#b7ccfa':'#efcc87',80,6);record(state,'defeated',e.id);if(e.boss&&state.stage===6)complete(6);if(!e.boss&&state.stage===3&&state.defeated.filter(id=>id.startsWith('dummy')).length>=3)complete(3);save();refreshHUD();}}
function cast(){if(paused()||elapsed<castUntil)return;const a=ABILITIES[selected];if(!unlocked(state,a.id))return;if((cooldowns.get(a.id)||0)>elapsed)return;if(mana<a.cost){toast('Brakuje mocy magicznej. Odpocznij chwilę.');return;}mana-=a.cost;cooldowns.set(a.id,elapsed+a.cooldown);castUntil=elapsed+.28;player.cast();audio.note(a.id==='protego'?240:760,.25,'sine',.035);const e=targetForSpell(),from=player.tip.getWorldPosition(V()),aim=e?e.pos.clone().add(V(0,e.type==='stone'?.1:1.2,0)):from.clone().add(V(-Math.sin(look.yaw)*25,.3,-Math.cos(look.yaw)*25));player.root.rotation.y=Math.atan2(aim.x-from.x,aim.z-from.z);
 if(a.id==='protego'){shieldUntil=elapsed+2.6;effects.shield(playerPos);return;}
 if(a.id==='lumos'){lumosUntil=elapsed+24;effects.ring(playerPos.clone().add(V(0,.1,0)),'#fce4a0',8,1);effects.sparks(from,'#ffebbd',70,4);if(state.stage===5){for(const r of entities.filter(x=>x.type==='rune')){if(r.pos.distanceTo(playerPos)<8&&record(state,'runes',r.id)){r.mesh.material.emissive.set('#f1cd7d');r.mesh.material.emissiveIntensity=1.2;effects.sparks(r.pos,'#f8d389',100,5);toast('Przebudzono leśną runę.');save();}}if(state.runes.length>=3)complete(5);refreshHUD();}return;}
 effects.projectile(from,aim,{color:a.color,fast:a.id==='expelliarmus',onHit:()=>{if(!e||e.hidden)return;if(a.id==='leviosa'){e.stunned=elapsed+4;effects.ring(e.pos.clone(),'#c8a3ff',2,1.1);if(e.type==='stone'&&state.stage===2&&record(state,'levitated',e.id)){e.mesh.material.emissive.set('#8060af');save();refreshHUD();if(state.levitated.length>=3)complete(2);}}else if(e.type==='enemy'){if(e.boss&&state.stage!==6){toast('Strażnika osłaniają runy. Najpierw ukończ zadanie z Lumosem.');return;}if(!e.boss&&state.stage<3){toast('Najpierw ukończ lekcję lewitacji u Flitwicka.');return;}lastCombat=elapsed;damageEnemy(e,stats(state).damage*(a.id==='expelliarmus'?2.2:1));if(a.id==='expelliarmus')e.stunned=elapsed+1.8;}}});
}
function hurt(amount){if(elapsed<dodgeUntil)return;if(elapsed<shieldUntil){effects.ring(playerPos.clone().add(V(0,.4,0)),'#a6ebff',2,.35);mana=Math.min(stats(state).mana,mana+5);audio.note(900,.14);return;}health=Math.max(0,health-amount);lastCombat=elapsed;$('#hurt').style.opacity=state.reducedMotion?'0':'.65';setTimeout(()=>$('#hurt').style.opacity='0',230);audio.note(70,.3,'triangle',.07);if(health===0){health=stats(state).health;mana=stats(state).mana;toast('Tracisz przytomność. Wracasz na dziedziniec; zachowujesz postęp.');travel('courtyard');}}
function potion(){if(paused())return;const result=usePotion(state,health);if(result.used){health=result.hp;save();refreshHUD();effects.sparks(playerPos.clone().add(V(0,1,0)),'#a4e3b9',70,3);toast('Eliksir przywrócił siły.');}else toast(state.potions?'Masz pełne zdrowie.':'Brak eliksirów. Uwarz je z dittany w lochach.');}
function dodge(){if(paused()||elapsed<dodgeCooldown)return;dodgeUntil=elapsed+.42;dodgeCooldown=elapsed+1.2;player.dodge();velocity.set(-Math.sin(look.yaw)*11,0,-Math.cos(look.yaw)*11);effects.ring(playerPos.clone().add(V(0,.08,0)),'#cbded7',1,.4);}
function getColliders(){if(room)return room.colliders;return zone==='courtyard'?[{x:23,z:31,r:4.55}]:world.colliders;}
function getBounds(){return room?room.bounds:zone==='courtyard'?{minX:11.5,maxX:33.5,minZ:16,maxZ:42}:{minX:-250,maxX:335,minZ:-250,maxZ:65};}
function updateMovement(dt){if(keys.has('ArrowLeft'))look.yaw+=dt*1.5;if(keys.has('ArrowRight'))look.yaw-=dt*1.5;let x=Number(keys.has('KeyD'))-Number(keys.has('KeyA')),z=Number(keys.has('KeyW')||keys.has('ArrowUp'))-Number(keys.has('KeyS')||keys.has('ArrowDown'));const length=Math.hypot(x,z);if(length){x/=length;z/=length;}const speed=keys.has('ShiftLeft')||keys.has('ShiftRight')?7.5:3.7;const dx=(x*Math.cos(look.yaw)-z*Math.sin(look.yaw))*speed,dz=(-x*Math.sin(look.yaw)-z*Math.cos(look.yaw))*speed;if(elapsed>dodgeUntil){velocity.x=damp(velocity.x,dx,length?12:16,dt);velocity.z=damp(velocity.z,dz,length?12:16,dt);}const previous=playerPos.clone(),next=moveCircle(playerPos,velocity.x*dt,velocity.z*dt,getColliders(),getBounds());const nextH=height(next.x,next.z);if(zone!=='grounds'||Math.abs(nextH-playerPos.y)<1.2){playerPos.x=next.x;playerPos.z=next.z;playerPos.y=damp(playerPos.y,nextH,24,dt);}const actual=previous.distanceTo(playerPos)/dt;if(actual>.1&&elapsed>castUntil){const angle=Math.atan2(playerPos.x-previous.x,playerPos.z-previous.z),diff=Math.atan2(Math.sin(angle-player.root.rotation.y),Math.cos(angle-player.root.rotation.y));player.root.rotation.y+=diff*(1-Math.exp(-15*dt));}player.root.position.copy(playerPos);player.update(dt,elapsed,actual);stepSound+=actual*dt;if(stepSound>1.5){stepSound=0;audio.step();}mana=Math.min(stats(state).mana,mana+stats(state).regen*dt);if(elapsed-lastCombat>10)health=Math.min(stats(state).health,health+2.5*dt);}
function updateCamera(dt,snap=false){const focus=playerPos.clone().add(V(0,1.5,0)),distance=look.distance;const desired=focus.clone().add(V(Math.sin(look.yaw)*distance,.75+Math.sin(look.pitch)*distance,Math.cos(look.yaw)*distance));if(room||zone==='courtyard'){const b=getBounds();desired.x=clamp(desired.x,b.minX+.2,b.maxX-.2);desired.z=clamp(desired.z,b.minZ+.2,b.maxZ-.2);}else{desired.y=Math.max(desired.y,height(desired.x,desired.z)+1);const colliders=getColliders();for(let i=1;i<=12;i++){const p=focus.clone().lerp(desired,i/12);if(colliders.some(c=>c.r?Math.hypot(p.x-c.x,p.z-c.z)<c.r+.15:Math.abs(p.x-c.x)<c.w/2+.15&&Math.abs(p.z-c.z)<c.d/2+.15)){desired.copy(focus).lerp(desired,Math.max(.15,(i-1)/12));break;}}}if(snap)camera.position.copy(desired);else camera.position.lerp(desired,1-Math.exp(-10*dt));camera.lookAt(focus);player.root.visible=camera.position.distanceTo(focus)>1.25;}
function updateActors(dt){for(const n of actors){let speed=0;if(n.route&&n!==dialogueNpc){n.pause-=dt;if(n.pause<=0){const [x,z]=n.route[n.waypoint],delta=V(x-n.pos.x,0,z-n.pos.z),distance=delta.length();if(distance<.25){n.waypoint=(n.waypoint+1)%n.route.length;n.pause=1.5+Math.random()*2;}else{speed=1.25;delta.normalize();const p=moveCircle(n.pos,delta.x*speed*dt,delta.z*speed*dt,getColliders(),getBounds(),.3);n.pos.x=p.x;n.pos.z=p.z;n.pos.y=height(p.x,p.z);const yaw=Math.atan2(delta.x,delta.z),diff=Math.atan2(Math.sin(yaw-n.actor.root.rotation.y),Math.cos(yaw-n.actor.root.rotation.y));n.actor.root.rotation.y+=diff*(1-Math.exp(-4*dt));}}}n.actor.update(dt,elapsed,speed,n===dialogueNpc);}
 for(const e of entities){if(e.hidden)continue;if(e.type==='enemy'){e.pos.y=damp(e.pos.y,e.baseY+(elapsed<e.stunned?2.2:0),5,dt);e.model.root.rotation.y=Math.atan2(playerPos.x-e.pos.x,playerPos.z-e.pos.z);e.hit=Math.max(0,e.hit-dt);e.model.body.rotation.z=Math.sin(e.hit*50)*e.hit*.5;e.model.gem.rotation.y+=dt;e.attack-=dt;const active=e.boss?state.stage===6:state.stage===3;if(active&&elapsed>e.stunned&&e.pos.distanceTo(playerPos)<(e.boss?24:17)&&e.attack<0){e.attack=e.boss?1.65:3.8;lastCombat=elapsed;const from=e.pos.clone().add(V(0,e.boss?2:1.5,0)),to=playerPos.clone().add(V(0,1,0));effects.projectile(from,to,{color:e.boss?'#b788ef':'#dda268',hostile:true,damage:e.boss?19:9});}if(active&&e.attack<.7&&elapsed>e.stunned)e.model.gem.scale.setScalar(1+Math.sin(elapsed*20)*.25);else e.model.gem.scale.setScalar(1);}
 else if(e.type==='stone'){e.pos.y=damp(e.pos.y,e.baseY+(elapsed<e.stunned?2+Math.sin(elapsed*2)*.15:0),4,dt);e.mesh.rotation.y+=dt*.3;}
 else if(e.type==='rune'||e.type==='herb'){e.mesh.position.y=e.baseY+Math.sin(elapsed*1.4+e.pos.x)*.08;e.mesh.rotation.y+=dt*.25;}}
}
function objectiveEntity(){const stage=state.stage;if(stage===0)return entities.find(e=>e.id==='minerva');if(stage===1)return entities.find(e=>e.id==='flitwick'||e.id==='charms-door');if(stage===2)return entities.find(e=>e.type==='stone'&&!state.levitated.includes(e.id))||entities.find(e=>e.id==='charms-door');if(stage===3)return entities.find(e=>e.type==='enemy'&&!e.boss&&!e.hidden)||entities.find(e=>e.id==='exit'||e.id==='castle-return');if(stage===4||stage===7)return entities.find(e=>e.id==='hagrid'||e.id==='grounds-door'||e.id==='exit');if(stage===5)return entities.find(e=>e.type==='rune'&&!state.runes.includes(e.id))||entities.find(e=>e.id==='grounds-door'||e.id==='exit');if(stage===6)return entities.find(e=>e.boss&&!e.hidden)||entities.find(e=>e.id==='grounds-door'||e.id==='exit');return null;}
function updateInteraction(){for(const e of entities){if(e.type==='door'&&e.mesh?.userData.label)e.mesh.userData.label.visible=false; if(e.type==='npc'){e.actor.root.children.forEach(o=>{if(o.isSprite)o.visible=e.pos.distanceTo(playerPos)>4&&e.pos.distanceTo(playerPos)<10;});}}nearby=null;let distance=Infinity;for(const e of entities){if(e.type==='enemy'||e.hidden)continue;const d=e.pos.distanceTo(playerPos),range=e.type==='npc'?3.1:e.type==='door'?2.4:2.5;if(d<range&&d<distance){nearby=e;distance=d;}}$('#interact').hidden=!nearby;if(nearby){$('#interaction-name').textContent=nearby.name;$('#interaction-kind').textContent=nearby.kind||{npc:'ROZMOWA',door:'PRZEJDŹ',herb:'ZBIERZ',chest:'OTWÓRZ',stone:'ZAKLĘCIE',rune:'STARA MAGIA'}[nearby.type];}target=targetForSpell();$('#target-hud').hidden=!target;if(target){$('#target-name').textContent=target.name;$('#target-health').style.width=(target.type==='enemy'?target.hp/target.maxHp*100:100)+'%';}const goal=objectiveEntity();if(goal){const p=goal.pos.clone().add(V(0,3.1,0)).project(camera);const d=goal.pos.distanceTo(playerPos);questMarker.hidden=p.z>1||p.z<-1||Math.abs(p.x)>.95||Math.abs(p.y)>.85||d<2.5;questMarker.style.left=(p.x*.5+.5)*innerWidth+'px';questMarker.style.top=(-p.y*.5+.5)*innerHeight+'px';questMarker.innerHTML=`<strong>◇</strong><small>${Math.round(d)} m</small>`;}else questMarker.hidden=true;
 guideMesh.visible=elapsed<guideUntil&&!!goal;if(guideMesh.visible){const delta=goal.pos.clone().sub(playerPos),length=Math.min(13,delta.length());delta.y=0;delta.normalize();for(let i=0;i<45;i++){const d=(i/44*length+(elapsed*.7)%1),x=playerPos.x+delta.x*d,z=playerPos.z+delta.z*d;guideArray.set([x,height(x,z)+.12+Math.sin(i*.5+elapsed*3)*.04,z],i*3);}guideGeo.attributes.position.needsUpdate=true;}
}
const radar=$('#radar'),ctx=radar.getContext('2d');function drawRadar(){const size=190,c=size/2,scale=zone==='courtyard'?3:room?2.5:.6;ctx.clearRect(0,0,size,size);ctx.save();ctx.beginPath();ctx.arc(c,c,93,0,Math.PI*2);ctx.clip();ctx.fillStyle='#12272cd9';ctx.fillRect(0,0,size,size);ctx.translate(c,c);ctx.rotate(-look.yaw);const xy=(x,z)=>[(x-playerPos.x)*scale,(z-playerPos.z)*scale];ctx.strokeStyle='#b4b99318';ctx.lineWidth=1;for(let i=-100;i<=100;i+=20){ctx.beginPath();ctx.moveTo(-100,i);ctx.lineTo(100,i);ctx.moveTo(i,-100);ctx.lineTo(i,100);ctx.stroke();}ctx.fillStyle='#76898145';const coll=getColliders();for(const b of coll){const p=xy(b.x,b.z);if(b.r){ctx.beginPath();ctx.arc(...p,b.r*scale,0,Math.PI*2);ctx.fill();}else ctx.fillRect(p[0]-b.w*scale/2,p[1]-b.d*scale/2,b.w*scale,b.d*scale);}const goal=objectiveEntity();for(const e of entities){if(e.hidden)continue;const p=xy(e.pos.x,e.pos.z);ctx.fillStyle=e===goal?'#f2cd7a':e.type==='enemy'?'#ce8a72':e.type==='door'?'#a9c3d0':e.type==='npc'?'#a1baa4':'#82956b';ctx.beginPath();ctx.arc(p[0],p[1],e===goal?4:2.4,0,Math.PI*2);ctx.fill();}ctx.restore();ctx.save();ctx.translate(c,c);ctx.fillStyle='#f5e9cd';ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(5,5);ctx.lineTo(0,2);ctx.lineTo(-5,5);ctx.closePath();ctx.fill();ctx.restore();ctx.strokeStyle='#c7ad6b44';ctx.beginPath();ctx.arc(c,c,65,0,Math.PI*2);ctx.stroke();$('#radar-label').textContent=room?'HOGWART':zone==='courtyard'?'DZIEDZINIEC':'BŁONIA';const angle=((look.yaw*180/Math.PI)%360+360)%360;$('#bearing').textContent=['N','NW','W','SW','S','SE','E','NE'][Math.round(angle/45)%8];}

function panel(html,label='HOGWART · SZLAKI MAGII'){disposeActivity();releasePointer();closeDialogue();$('#panel-kicker').textContent=label;$('#panel-content').innerHTML=html;if(!$('#panel').open)$('#panel').showModal();}
function showCurrentActivity(){
 if(!roomId||!ACTIVITIES[roomId])return;
 const id=roomId,info=ROOMS.find(r=>r.id===id);
 panel('',info.name.toLocaleUpperCase('pl')+' · PRAKTYKA');
 activeActivity=openRoomActivity(id,{panel:$('#panel-content'),state,audio,toast,complete:completed=>{
  const before=level(state);if(!finishRoom(state,completed))return;
  if(level(state)>before){health=stats(state).health;mana=stats(state).mana;}
  save();refreshHUD();
 }});
}
function showJournal(tab='quests'){
 const tabs=`<div class="panel-tabs">${[['quests','Zadania'],['practice','Praktyka'],['talents','Talenty'],['inventory','Ekwipunek'],['spells','Zaklęcia']].map(([id,name])=>`<button data-journal="${id}" class="${id===tab?'active':''}">${name}</button>`).join('')}</div>`;let content='';
 if(tab==='quests')content=`<h2>Światło między drzewami</h2><p>Rozdział I · ${state.stage} / 8 etapów ukończonych</p>${QUESTS.slice(0,8).map((q,i)=>`<div class="quest-row ${i<state.stage?'done':''}"><span>${i<state.stage?'✓':i===state.stage?'◇':'·'}</span><div><strong>${q.title}</strong><p>${i<=state.stage?q.objective:'Dalszy ciąg opowieści…'}</p>${i===state.stage?`<p>${q.hint}</p>`:''}</div></div>`).join('')}`;
 if(tab==='practice')content=`<h2>Praktyka w Hogwarcie</h2><p>${ROOMS.filter(r=>state.roomsCompleted.includes(r.id)).length} / ${ROOMS.length} ćwiczeń zaliczonych. Pierwsze zaliczenie: +${ROOM_REWARD.xp} PD i +${ROOM_REWARD.coins} galeonów.</p><div class="room-grid">${ROOMS.map(r=>`<button data-practice-room="${r.id}"><span class="practice-status">${state.roomsCompleted.includes(r.id)?'✓ ZALICZONE':'DO ODKRYCIA'}</span>${safe(r.name)}<small>${safe(ACTIVITIES[r.id].title)}</small></button>`).join('')}</div>`;
 if(tab==='talents')content=`<h2>Talenty</h2><p>Poziom ${level(state)} · ${points(state)} pkt talentów do wydania. Każde 200 PD daje kolejny poziom.</p><div class="talent-grid">${[['power','ϟ','Siła zaklęć','Każdy stopień zwiększa obrażenia czarów o 6.'],['focus','✧','Skupienie','Każdy stopień daje +20 mocy i +2 regeneracji na sekundę.'],['vitality','♡','Wytrzymałość','Każdy stopień dodaje 25 maksymalnego zdrowia.']].map(([id,icon,title,desc])=>`<div class="talent-card"><span>${icon}</span><h3>${title}</h3><p>${desc}</p><button data-talent="${id}" ${points(state)<1||state.talents[id]>=3?'disabled':''}>${'◆'.repeat(state.talents[id])}${'◇'.repeat(3-state.talents[id])} · Rozwiń</button></div>`).join('')}</div>`;
 if(tab==='inventory')content=`<h2>Torba ucznia</h2><div class="stats-grid"><div><strong>${state.coins}</strong><small>GALEONY</small></div><div><strong>${state.herbs}</strong><small>LIŚCIE DITTANY</small></div><div><strong>${state.potions}</strong><small>ELIKSIRY ZDROWIA</small></div></div><div class="item-row"><span>✧</span><div><h3>Twoja różdżka</h3><p>Jesion · smocze serce · 12 cali. Stały towarzysz Twojej pierwszej przygody.</p></div></div><div class="item-row"><span>♧</span><div><h3>Eliksir zdrowia</h3><p>Przywraca 65 punktów zdrowia. Użyj R w grze. Trzy liście dittany wystarczą na jedną porcję w lochach Snape’a.</p></div></div><p>Postęp zapisuje się automatycznie w tej przeglądarce. Atlas Hogwartu ma osobny zapis.</p>`;
 if(tab==='spells')content=`<h2>Księga zaklęć</h2>${ABILITIES.map(a=>`<div class="item-row"><span style="font-size:30px;color:${a.color}">${a.icon}</span><div><h3>${a.name} ${unlocked(state,a.id)?'':'· zamknięte'}</h3><p>${a.desc}<br>${a.cost} mocy · odnowienie ${a.cooldown} s · klawisz ${a.key}</p></div></div>`).join('')}`;
 panel(tabs+content,'DZIENNIK · '+state.name.toUpperCase());$$('[data-practice-room]').forEach(b=>b.onclick=()=>travel(b.dataset.practiceRoom));$$('[data-journal]').forEach(b=>b.onclick=()=>showJournal(b.dataset.journal));$$('[data-talent]').forEach(b=>b.onclick=()=>{if(upgrade(state,b.dataset.talent)){health=Math.min(stats(state).health,health+25);mana=Math.min(stats(state).mana,mana+20);save();refreshHUD();showJournal('talents');}});
}
function showMap(){panel(`<h2>Mapa Hogwartu</h2><p>Wybierz punkt podróży lub wróć do pieszej eksploracji. Złoty znacznik wskazuje bieżące zadanie.</p><div class="map-layout"><svg class="map-illustration" viewBox="0 0 360 340" role="img" aria-label="Schemat błoni"><path d="M36 100Q65 40 150 38T315 91L330 249Q237 319 143 292T34 218Z"/><path d="M178 156L76 178L59 90M178 156L274 73M178 156L201 253" stroke-dasharray="4 5"/><path d="M104 231Q210 173 292 218T188 294T104 231Z" style="fill:#4a7c8b33"/><path d="M53 119L72 62L88 123M70 124L95 74L113 131M93 134L121 91L140 142"/><circle cx="178" cy="156" r="7"/><circle cx="76" cy="178" r="4"/><circle cx="59" cy="90" r="4"/><circle cx="274" cy="73" r="4"/><text x="189" y="154">Hogwart</text><text x="75" y="197">Chatka Hagrida</text><text x="33" y="50">Zakazany Las</text><text x="241" y="58">Hogsmeade</text><text x="177" y="252">Czarne Jezioro</text><text x="145" y="320" style="font-size:8px">SCHEMAT ORIENTACYJNY</text></svg><div class="travel-list">${[['courtyard','Dziedziniec'],['charms','Sala zaklęć'],['great-hall','Wielka Sala'],['potions','Lochy eliksirów'],['grounds','Błonia · droga do Hagrida'],['forest','Skraj Zakazanego Lasu'],['hogsmeade','Hogsmeade']].map(([id,name])=>`<button data-travel="${id}">${name}<small>${state.visited.includes(id)?'ODKRYTE':'PODRÓŻ'} →</small></button>`).join('')}<button id="map-rooms">Pozostałe sale Hogwartu <small>${ROOMS.length} WNĘTRZ →</small></button></div></div>`,'MAPA ŚWIATA');$$('[data-travel]').forEach(b=>b.onclick=()=>travel(b.dataset.travel));$('#map-rooms').onclick=showRooms;}
function showRooms(){
 const completed=ROOMS.filter(r=>state.roomsCompleted.includes(r.id)).length;
 panel(`<h2>Za drzwiami Hogwartu</h2><p>${completed} / ${ROOMS.length} ćwiczeń zaliczonych. W każdej sali znajdziesz odrębną scenografię i stanowisko praktyki po prawej stronie wejścia. Porozmawiaj z profesorem lub podejdź do stanowiska i naciśnij E.</p><input id="room-search" aria-label="Szukaj sali" placeholder="Szukaj miejsca, profesora lub ćwiczenia…"><div class="room-grid" id="room-list"></div>`,'KORYTARZE SZKOŁY');
 const render=()=>{const q=$('#room-search').value.toLocaleLowerCase('pl');$('#room-list').innerHTML=ROOMS.filter(r=>(r.name+' '+r.professor+' '+ACTIVITIES[r.id].title).toLocaleLowerCase('pl').includes(q)).map(r=>`<button data-room="${r.id}"><span class="practice-status">${state.roomsCompleted.includes(r.id)?'✓ ZALICZONE':state.visited.includes(r.id)?'ODKRYTE':'DO ODKRYCIA'}</span>${safe(r.name)}<small>${safe(ACTIVITIES[r.id].title)}</small></button>`).join('');$$('[data-room]').forEach(b=>b.onclick=()=>travel(b.dataset.room));};$('#room-search').oninput=render;render();
}
function setQuality(q,announce=false){quality=q;state.quality=q;graphics.setQuality(q);environment.setQuality(q);atmosphere.setQuality(q);sun.shadow.mapSize.setScalar(q==='ultra'?4096:q==='high'?2048:1024);sun.shadow.map?.dispose();sun.shadow.map=null;renderer.shadowMap.needsUpdate=true;if(announce){save();toast('Grafika: '+{ultra:'Ultra',high:'Wysoka',balanced:'Płynność'}[q]);}}
function showMenu(){panel(`<h2>Ustawienia gry</h2><p>Gra jest wstrzymana. Twój zapis jest niezależny od atlasu Hogwartu.</p><div class="settings-row"><div>Jakość grafiki<small>Ultra: odbicia, cienie 4K, kontaktowe cieniowanie. Płynność: lżejszy rendering.</small></div><select id="quality-select" aria-label="Jakość grafiki">${[['balanced','Płynność'],['high','Wysoka'],['ultra','Ultra']].map(([v,n])=>`<option value="${v}" ${quality===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="settings-row"><div>Pora dnia<small>Zmiana dotyczy otoczenia zamku.</small></div><button id="change-time">${['Złota godzina','Noc','Poranek'][timeMode]} ↻</button></div><div class="settings-row"><div>Dźwięk<small>Subtelne tło, kroki i dźwięki zaklęć.</small></div><button id="sound-toggle">${audio.enabled?'Włączony':'Wyłączony'}</button></div><div class="menu-buttons"><button class="primary" id="resume">Wróć do gry →</button><button id="controls-help">Sterowanie</button><button id="accessibility">Dostępność</button><button id="about-game">O projekcie</button><button id="return-title">Ekran tytułowy</button></div>`,'PAUZA');$('#quality-select').onchange=e=>setQuality(e.target.value,true);$('#change-time').onclick=()=>{timeMode=(timeMode+1)%3;setLighting();$('#change-time').textContent=['Złota godzina','Noc','Poranek'][timeMode]+' ↻';};$('#sound-toggle').onclick=()=>{state.sound=audio.toggle();save();$('#sound-toggle').textContent=audio.enabled?'Włączony':'Wyłączony';};$('#resume').onclick=()=>$('#panel').close();$('#controls-help').onclick=showControls;$('#accessibility').onclick=showAccessibility;$('#about-game').onclick=showAbout;$('#return-title').onclick=()=>{save();$('#panel').close();switchZone('courtyard');playing=false;$('#hud').hidden=true;$('#title-screen').hidden=false;$('#continue-game').hidden=false;player.root.visible=false;};}
function applyPreferences(){document.body.classList.toggle('large-text',state.largeText);document.body.classList.toggle('high-contrast',state.highContrast);document.body.classList.toggle('reduced-motion',state.reducedMotion);}
function showAccessibility(){panel(`<h2>Dostępność</h2><p>Dostosuj czytelność interfejsu. Ustawienia są zapisywane razem z Twoją grą.</p>${[['largeText','Większy tekst','Powiększa tekst zadań, dialogów i menu.'],['highContrast','Wysoki kontrast','Dodaje nieprzezroczyste tła pod ważnymi informacjami.'],['reducedMotion','Ograniczony ruch i błyski','Wyłącza błyski obrażeń, animacje interfejsu i ruch panoramy w menu.']].map(([id,title,desc])=>`<div class="settings-row"><div>${title}<small>${desc}</small></div><button data-pref="${id}" aria-pressed="${state[id]}">${state[id]?'Włączone':'Wyłączone'}</button></div>`).join('')}<p>Informacje o czarach mają nazwę, symbol i numer klawisza. Postęp zadań jest podany tekstem; kolor nie jest jedyną wskazówką.</p>`,'DOSTĘPNOŚĆ');$$('[data-pref]').forEach(b=>b.onclick=()=>{const key=b.dataset.pref;state[key]=!state[key];applyPreferences();save();showAccessibility();});}
function showControls(){panel(`<h2>Sterowanie</h2><div class="item-row"><kbd>W A S D</kbd><p>Ruch względem kamery. Shift — sprint. Alt — unik z krótką niewrażliwością.</p></div><div class="item-row"><kbd>PPM</kbd><p>Przytrzymaj prawy przycisk i poruszaj myszą, aby się rozejrzeć. Scroll przybliża kamerę. Strzałki ← i → obracają kamerę z klawiatury. „Zablokuj kursor” włącza stałe rozglądanie; Esc uwalnia kursor.</p></div><div class="item-row"><kbd>1–5</kbd><p>Wybierz zaklęcie. Lewy przycisk myszy lub Spacja rzuca je na cel przed Tobą. Podejdź bliżej, aby trafić.</p></div><div class="item-row"><kbd>E</kbd><p>Rozmowa, zebranie przedmiotu lub przejście przez drzwi. R — eliksir. G — świetlista wskazówka. M — mapa. J — dziennik.</p></div><p>Na ekranie dotykowym przeciągnij widok, użyj strzałek i przycisku różdżki. Stuknij komunikat rozmowy lub przejścia. Wszystkie dialogi mają przyciski odpowiedzi.</p>`,'STEROWANIE');}
function showAbout(){panel(`<h2>Nowa historia. Ten sam magiczny świat.</h2><p>„Szlaki Magii” to osobny, fanowski prototyp RPG. Pierwszy grywalny rozdział zawiera osiem etapów zadania, dialogi, walkę zaklęciami, zbieranie składników, eliksiry, doświadczenie i talenty.</p><p>Scenografia wykorzystuje modele i materiały z naszego atlasu. Nowe sterowanie, postacie, animacje, przeciwnicy, dialogi i zapis należą wyłącznie do gry. Wnętrza są osobnymi scenami połączonymi drzwiami i mapą; zamek jest interpretacją filmową, nie rekonstrukcją 1:1. Każde z 40 wnętrz ma własne dekoracje i ćwiczenie: zagadkę, manipulację przedmiotami lub próbę taktyczną. Pierwsze zaliczenia dają doświadczenie i monety; kolejne podejścia służą treningowi. Ćwiczenia odbywają się na osobnych planszach, a walka i główna nauka zaklęć w świecie 3D.</p><p>Proceduralne modele i animacje są autorskie. Fotograficzne tekstury PBR: Poly Haven, CC0. Three.js: MIT. Font Cormorant: SIL Open Font License. Dialogi i zadania są oryginalne. Projekt nie jest oficjalną grą Warner Bros. ani Portkey Games.</p><p class="source-links"><a href="https://polyhaven.com/a/stone_brick_wall_001" target="_blank" rel="noreferrer">Kamień</a><a href="https://polyhaven.com/a/wood_floor_worn" target="_blank" rel="noreferrer">Drewno</a><a href="https://polyhaven.com/a/rocky_terrain_02" target="_blank" rel="noreferrer">Teren</a></p>`,'O PROJEKCIE I ŹRÓDŁACH');}
$('#houses').innerHTML=Object.entries(HOUSES).map(([id,h])=>`<button data-house="${id}" style="--house:${h.color}" class="${state.house===id?'selected':''}"><i>◇</i>${h.name}</button>`).join('');let chosenHouse=state.house;$$('[data-house]').forEach(b=>b.onclick=()=>{chosenHouse=b.dataset.house;$$('[data-house]').forEach(x=>x.classList.toggle('selected',x===b));});$('#player-name').value=state.name;$('#continue-game').hidden=!state.started;
function start(resume=false){if(!resume){if(state.started){panel('<h2>Nowa przygoda?</h2><p>Rozpoczęcie nowej przygody zastąpi zapis tej gry w tej przeglądarce. Zapis atlasu pozostanie bez zmian.</p><div class="menu-buttons"><button class="primary" id="confirm-new">Rozpocznij od nowa</button><button id="cancel-new">Zachowaj zapis</button></div>');$('#confirm-new').onclick=()=>{state=newState();$('#panel').close();start(false);};$('#cancel-new').onclick=()=>$('#panel').close();return;}state.house=chosenHouse;state.name=$('#player-name').value.trim().slice(0,24)||'Adept';state.started=true;}player.setColor(HOUSES[state.house].color);health=stats(state).health;mana=stats(state).mana;playing=true;$('#title-screen').hidden=true;$('#hud').hidden=false;player.root.visible=true;switchZone('courtyard');save();if(state.sound&&!audio.enabled)audio.toggle();toast(resume?'Witaj ponownie. Twój postęp został wczytany.':'WASD — ruch · PPM — kamera · E — rozmowa');}
$('#start-game').onclick=()=>start(false);$('#continue-game').onclick=()=>start(true);$('#about-title').onclick=showAbout;$('#open-journal').onclick=()=>showJournal();$('#open-map').onclick=showMap;$('#open-menu').onclick=showMenu;$('#close-panel').onclick=()=>$('#panel').close();$('#leave-dialogue').onclick=closeDialogue;$('#interact').onclick=interact;$('#potion').onclick=potion;$('#guide-button').onclick=()=>{guideUntil=elapsed+20;toast(QUESTS[state.stage].hint);};$('#mobile-cast').onclick=cast;$('#mobile-dodge').onclick=dodge;
$('#panel').addEventListener('close',()=>{keys.clear();disposeActivity();});$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const b=$('#panel').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('#panel').close();}});
$('#mouse-lock').onclick=()=>{renderer.domElement.requestPointerLock?.();};
window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.code==='Escape'){if(dialogueNpc){closeDialogue();e.preventDefault();}else if(!$('#panel').open&&playing&&!document.pointerLockElement)showMenu();return;}if(!playing)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','AltLeft','AltRight'].includes(e.code))e.preventDefault();if(paused())return;keys.add(e.code);if(e.repeat)return;if(/^Digit[1-5]$/.test(e.code))selectSpell(Number(e.code.at(-1))-1);if(e.code==='KeyE')interact();if(e.code==='Space')cast();if(e.code==='KeyR')potion();if(e.code==='KeyJ')showJournal();if(e.code==='KeyM')showMap();if(e.code==='KeyG'){guideUntil=elapsed+20;toast(QUESTS[state.stage].hint);}if(e.code==='AltLeft'||e.code==='AltRight')dodge();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();dragging=false;});document.addEventListener('visibilitychange',()=>keys.clear());
renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('pointerdown',e=>{if(paused())return;if(e.button===2||e.pointerType==='touch'){dragging=true;pointerId=e.pointerId;lastPointer={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);}else if(e.button===0)cast();});renderer.domElement.addEventListener('pointermove',e=>{if(paused())return;if(document.pointerLockElement===renderer.domElement){look.yaw-=e.movementX*.0035;look.pitch=clamp(look.pitch+e.movementY*.0025,-.25,.8);}else if(dragging&&e.pointerId===pointerId){look.yaw-=(e.clientX-lastPointer.x)*.006;look.pitch=clamp(look.pitch+(e.clientY-lastPointer.y)*.004,-.25,.8);lastPointer={x:e.clientX,y:e.clientY};}});const pointerUp=()=>dragging=false;renderer.domElement.addEventListener('pointerup',pointerUp);renderer.domElement.addEventListener('pointercancel',pointerUp);renderer.domElement.addEventListener('wheel',e=>{if(paused())return;e.preventDefault();look.distance=clamp(look.distance+e.deltaY*.006,2.5,10);},{passive:false});
$$('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keys.add(b.dataset.key);b.setPointerCapture(e.pointerId);};const stop=()=>keys.delete(b.dataset.key);b.onpointerup=stop;b.onpointercancel=stop;b.onlostpointercapture=stop;});
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();graphics.resize(innerWidth,innerHeight);});window.addEventListener('pagehide',()=>{if(state.started)save();});
let last=performance.now(),accumulator=0,frames=0,frameSeconds=0,uiTick=0,slowSeconds=0,adapted=false;
function frame(now){requestAnimationFrame(frame);const wallDt=Math.min((now-last)/1000,.1);last=now;const running=!paused();if(running){accumulator+=wallDt;while(accumulator>=1/60){elapsed+=1/60;updateMovement(1/60);updateActors(1/60);effects.update(1/60,playerPos,hurt);accumulator-=1/60;}updateCamera(wallDt);lumos.position.copy(playerPos).y+=1.7;lumos.intensity=elapsed<lumosUntil?22:0;uiTick+=wallDt;if(uiTick>.09){uiTick=0;updateInteraction();drawRadar();$('#health-fill').style.width=health/stats(state).health*100+'%';$('#health-label').textContent=Math.ceil(health)+' / '+stats(state).health;$('#mana-fill').style.width=mana/stats(state).mana*100+'%';$('#mana-label').textContent=Math.ceil(mana)+' / '+stats(state).mana;$$('[data-spell]').forEach((b,i)=>{const remaining=(cooldowns.get(ABILITIES[i].id)||0)-elapsed;const node=b.querySelector('.cooldown');node.hidden=remaining<=0;if(remaining>0)node.textContent=remaining.toFixed(1);});}}
 else{accumulator=0;if(!playing){const t=state.reducedMotion?0:now*.000015;camera.position.set(155+Math.sin(t)*18,93,188);camera.lookAt(0,43,2);player.root.visible=false;guideMesh.visible=false;}if(dialogueNpc)dialogueNpc.actor?.update(wallDt,elapsed+now*.0001,0,true);}
 if(room){room.update(elapsed);roomIdentity?.update(elapsed);activityProps?.update(elapsed);}else world.update(elapsed);environment.update(running?wallDt:0);sky.update(elapsed);atmosphere.update(running?wallDt:0,elapsed,playerPos);graphics.render(wallDt);frames++;frameSeconds+=wallDt;if(frameSeconds>=2){const fps=Math.round(frames/frameSeconds);$('#fps').textContent=fps+' FPS';if(running&&!adapted&&quality==='high'&&fps<29)slowSeconds+=frameSeconds;else slowSeconds=0;if(slowSeconds>6){adapted=true;setQuality('balanced');toast('Włączono tryb Płynność. Ultra możesz wybrać w ustawieniach.');}frames=0;frameSeconds=0;}}
applyPreferences();setQuality(quality);refreshHUD();requestAnimationFrame(frame);setTimeout(()=>{$('#loading').hidden=true;$('#title-screen').hidden=false;},800);
